-- Generated by scripts/build_osi.py from the ontology. Do not edit.
CREATE SCHEMA IF NOT EXISTS GLP.SEMANTIC;

CREATE OR REPLACE VIEW GLP.SEMANTIC.PRESCRIPTION_CLASS
  COMMENT = 'One row per prescription and therapeutic class (US.PRODUCT_CLASS: substance classes and all broader classes).'
AS SELECT p.PRESCRIPTION_ID, pc.CLASS_ID, p.TOTAL_CLAIMS, p.TOTAL_30DAY_FILLS, p.TOTAL_DRUG_COST
FROM GLP.US.PRESCRIPTION p JOIN GLP.US.PRODUCT_CLASS pc ON pc.PRODUCT_ID = p.PRODUCT_ID;

CREATE OR REPLACE VIEW GLP.SEMANTIC.PRESCRIPTION_CLASS_COMPANY
  COMMENT = 'One row per prescription, therapeutic class and marketing authorization holder (none for unbranded generics).'
AS SELECT p.PRESCRIPTION_ID, pc.CLASS_ID, pm.ORGANIZATION_ID, COALESCE(pm.ORGANIZATION_ID, 'none') AS ORGANIZATION_KEY,
       COALESCE(o.NAME_EN, 'generic (no single manufacturer)') AS MANUFACTURER, p.TOTAL_CLAIMS,
       p.TOTAL_CLAIMS / COUNT(*) OVER (PARTITION BY p.PRESCRIPTION_ID, pc.CLASS_ID) AS CLAIMS_ALLOCATED, p.TOTAL_DRUG_COST
FROM GLP.US.PRESCRIPTION p
JOIN GLP.US.PRODUCT_CLASS pc ON pc.PRODUCT_ID = p.PRODUCT_ID
LEFT JOIN GLP.US.PRODUCT_MANUFACTURER pm ON pm.PRODUCT_ID = p.PRODUCT_ID
LEFT JOIN GLP.US.ORGANIZATION o ON o.ORGANIZATION_ID = pm.ORGANIZATION_ID;

-- OWL defined classes (GLP1Prescriber, GLP1Product, SGLT2Prescriber, SGLT2Product) as flags: what a reasoner infers, spelled out in SQL.
CREATE OR REPLACE VIEW GLP.SEMANTIC.PRESCRIBER_PROFILE
  COMMENT = 'US.PRESCRIBER with the OWL defined classes of the ontology as flags.'
AS SELECT d.*, COALESCE(f.IS_GLP1_PRESCRIBER, FALSE) AS IS_GLP1_PRESCRIBER, COALESCE(f.IS_SGLT2_PRESCRIBER, FALSE) AS IS_SGLT2_PRESCRIBER
FROM GLP.US.PRESCRIBER d LEFT JOIN (
  SELECT p.PRESCRIBER_ID, BOOLOR_AGG(pc.CLASS_ID = 'GLP1ReceptorAgonist') AS IS_GLP1_PRESCRIBER, BOOLOR_AGG(pc.CLASS_ID = 'SGLT2Inhibitor') AS IS_SGLT2_PRESCRIBER
  FROM GLP.US.PRESCRIPTION p JOIN GLP.US.PRODUCT_CLASS pc ON pc.PRODUCT_ID = p.PRODUCT_ID
  GROUP BY p.PRESCRIBER_ID) f ON f.PRESCRIBER_ID = d.PRESCRIBER_ID;

CREATE OR REPLACE VIEW GLP.SEMANTIC.PRODUCT_PROFILE
  COMMENT = 'US.PRODUCT with the OWL defined classes of the ontology as flags.'
AS SELECT d.*, COALESCE(f.IS_GLP1_PRODUCT, FALSE) AS IS_GLP1_PRODUCT, COALESCE(f.IS_SGLT2_PRODUCT, FALSE) AS IS_SGLT2_PRODUCT
FROM GLP.US.PRODUCT d LEFT JOIN (
  SELECT pc.PRODUCT_ID, BOOLOR_AGG(pc.CLASS_ID = 'GLP1ReceptorAgonist') AS IS_GLP1_PRODUCT, BOOLOR_AGG(pc.CLASS_ID = 'SGLT2Inhibitor') AS IS_SGLT2_PRODUCT
  FROM GLP.US.PRODUCT_CLASS pc GROUP BY pc.PRODUCT_ID) f ON f.PRODUCT_ID = d.PRODUCT_ID;

-- JAPAN_MARKET. Unified-name generics have no marketing authorization holder.
CREATE OR REPLACE VIEW GLP.SEMANTIC.JP_PRODUCT_PROFILE
  COMMENT = 'JP.PRODUCT with the OWL defined classes as flags, its substances and its company (corporate group, else holder).'
AS SELECT d.*, COALESCE(f.IS_GLP1_PRODUCT, FALSE) AS IS_GLP1_PRODUCT, COALESCE(f.IS_SGLT2_PRODUCT, FALSE) AS IS_SGLT2_PRODUCT,
       sub.ACTIVE_SUBSTANCES, sub.ACTIVE_SUBSTANCES_JA, m.NAME_EN AS MAH_NAME, m.NAME_JA AS MAH_NAME_JA,
       COALESCE(g.NAME_EN, m.NAME_EN, '(no single holder: unified-name generic)') AS COMPANY,
       COALESCE(g.NAME_JA, m.NAME_JA, '（統一名収載の後発品）') AS COMPANY_JA
FROM GLP.JP.PRODUCT d
LEFT JOIN (SELECT pc.PRODUCT_ID, BOOLOR_AGG(pc.CLASS_ID = 'GLP1ReceptorAgonist') AS IS_GLP1_PRODUCT, BOOLOR_AGG(pc.CLASS_ID = 'SGLT2Inhibitor') AS IS_SGLT2_PRODUCT
           FROM GLP.JP.PRODUCT_CLASS pc GROUP BY pc.PRODUCT_ID) f ON f.PRODUCT_ID = d.PRODUCT_ID
LEFT JOIN (SELECT ps.PRODUCT_ID,
                  LISTAGG(v.PREF_LABEL_EN, ' + ') WITHIN GROUP (ORDER BY v.PREF_LABEL_EN) AS ACTIVE_SUBSTANCES,
                  LISTAGG(COALESCE(v.PREF_LABEL_JA, v.PREF_LABEL_EN), '・') WITHIN GROUP (ORDER BY v.PREF_LABEL_EN)
                    AS ACTIVE_SUBSTANCES_JA
           FROM GLP.JP.PRODUCT_SUBSTANCE ps JOIN GLP.VOCAB.SUBSTANCE v ON v.SUBSTANCE_ID = ps.SUBSTANCE_ID
           GROUP BY ps.PRODUCT_ID) sub ON sub.PRODUCT_ID = d.PRODUCT_ID
LEFT JOIN GLP.JP.ORGANIZATION m ON m.ORGANIZATION_ID = d.ORGANIZATION_ID
LEFT JOIN GLP.US.ORGANIZATION g ON g.ORGANIZATION_ID = m.CORPORATE_GROUP_ID;

CREATE OR REPLACE VIEW GLP.SEMANTIC.JP_NATIONAL_VALUE_CLASS
  COMMENT = 'National totals x therapeutic class (JP.PRODUCT_CLASS), with the value in yen and the class and market totals as share denominators; masked totals left out.'
AS SELECT t.PRODUCT_ID, t.CARE_SETTING_ID, pc.CLASS_ID, t.TOTAL_QUANTITY, t.TOTAL_QUANTITY * p.NHI_PRICE AS VALUE_YEN,
       SUM(t.TOTAL_QUANTITY * p.NHI_PRICE) OVER (PARTITION BY pc.CLASS_ID) AS CLASS_TOTAL_VALUE_YEN,
       SUM(IFF(pc.CLASS_ID = 'DrugsUsedInDiabetes', t.TOTAL_QUANTITY * p.NHI_PRICE, 0)) OVER () AS MARKET_TOTAL_VALUE_YEN
FROM GLP.JP.NATIONAL_TOTAL t JOIN GLP.JP.PRODUCT p ON p.PRODUCT_ID = t.PRODUCT_ID
JOIN GLP.JP.PRODUCT_CLASS pc ON pc.PRODUCT_ID = t.PRODUCT_ID
WHERE NOT t.IS_MASKED;

CREATE OR REPLACE VIEW GLP.SEMANTIC.JP_PREFECTURE_VALUE_CLASS
  COMMENT = 'NDB cells of the prefecture breakdown x therapeutic class, with the value in yen; masked cells left out.'
AS SELECT q.PRODUCT_ID, q.CARE_SETTING_ID, q.PREFECTURE_CODE, pc.CLASS_ID, q.QUANTITY,
       q.QUANTITY * p.NHI_PRICE AS VALUE_YEN
FROM GLP.JP.QUANTITY q JOIN GLP.JP.PRODUCT p ON p.PRODUCT_ID = q.PRODUCT_ID
JOIN GLP.JP.PRODUCT_CLASS pc ON pc.PRODUCT_ID = q.PRODUCT_ID
WHERE q.BREAKDOWN = 'prefecture' AND NOT q.IS_MASKED;

CREATE OR REPLACE VIEW GLP.SEMANTIC.JP_MONTH_VALUE_CLASS
  COMMENT = 'NDB cells of the month breakdown x therapeutic class, with the value in yen; masked cells left out.'
AS SELECT q.PRODUCT_ID, q.CARE_SETTING_ID, q.MONTH, pc.CLASS_ID, q.QUANTITY,
       q.QUANTITY * p.NHI_PRICE AS VALUE_YEN, IFF(p.IS_GENERIC, q.QUANTITY, 0) AS GENERIC_QUANTITY
FROM GLP.JP.QUANTITY q JOIN GLP.JP.PRODUCT p ON p.PRODUCT_ID = q.PRODUCT_ID
JOIN GLP.JP.PRODUCT_CLASS pc ON pc.PRODUCT_ID = q.PRODUCT_ID
WHERE q.BREAKDOWN = 'month' AND NOT q.IS_MASKED;

CREATE OR REPLACE VIEW GLP.SEMANTIC.JP_SEX_AGE_VALUE_CLASS
  COMMENT = 'NDB cells of the sex-age breakdown x therapeutic class, with the value in yen; masked cells left out.'
AS SELECT q.PRODUCT_ID, q.CARE_SETTING_ID, q.SEX_AGE_CODE, pc.CLASS_ID, q.QUANTITY,
       q.QUANTITY * p.NHI_PRICE AS VALUE_YEN, IFF(g.MIN_AGE >= 75, q.QUANTITY * p.NHI_PRICE, 0) AS VALUE_YEN_AGE75PLUS, IFF(g.SEX = 'F', q.QUANTITY * p.NHI_PRICE, 0) AS VALUE_YEN_FEMALE
FROM GLP.JP.QUANTITY q JOIN GLP.JP.PRODUCT p ON p.PRODUCT_ID = q.PRODUCT_ID
JOIN GLP.JP.PRODUCT_CLASS pc ON pc.PRODUCT_ID = q.PRODUCT_ID
LEFT JOIN GLP.VOCAB.SEX_AGE_GROUP g ON g.SEX_AGE_CODE = q.SEX_AGE_CODE
WHERE q.BREAKDOWN = 'sex-age' AND NOT q.IS_MASKED;

-- One view per dataset of the semantic views, with the logical field names as column names.
CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_PRESCRIPTION
  COMMENT = 'Dataset prescription of the semantic view DIABETES_MARKET.'
AS SELECT s.PRESCRIPTION_ID AS PRESCRIPTION_ID, s.PRESCRIBER_ID AS PRESCRIBER_ID, s.PRODUCT_ID AS PRODUCT_ID, s.DATA_YEAR AS DATA_YEAR, s.BENEFICIARIES_SUPPRESSED AS BENEFICIARIES_SUPPRESSED, s.TOTAL_CLAIMS AS CLAIMS, s.TOTAL_30DAY_FILLS AS FILLS_30DAY, s.TOTAL_DAY_SUPPLY AS DAY_SUPPLY, s.TOTAL_DRUG_COST AS DRUG_COST, s.TOTAL_BENEFICIARIES AS BENEFICIARIES
FROM GLP.US.PRESCRIPTION s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_PRESCRIPTION_CLASS
  COMMENT = 'Dataset prescription_class of the semantic view DIABETES_MARKET.'
AS SELECT s.PRESCRIPTION_ID AS PRESCRIPTION_ID, s.CLASS_ID AS CLASS_ID, s.TOTAL_CLAIMS AS CLAIMS, s.TOTAL_30DAY_FILLS AS FILLS_30DAY, s.TOTAL_DRUG_COST AS DRUG_COST
FROM GLP.SEMANTIC.PRESCRIPTION_CLASS s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_PRESCRIPTION_CLASS_COMPANY
  COMMENT = 'Dataset prescription_class_company of the semantic view DIABETES_MARKET.'
AS SELECT s.PRESCRIPTION_ID AS PRESCRIPTION_ID, s.CLASS_ID AS CLASS_ID, s.MANUFACTURER AS MANUFACTURER, s.TOTAL_CLAIMS AS CLAIMS, s.CLAIMS_ALLOCATED AS CLAIMS_ALLOCATED, s.TOTAL_DRUG_COST AS DRUG_COST, s.ORGANIZATION_KEY AS ORGANIZATION_KEY, s.ORGANIZATION_ID AS ORGANIZATION_ID
FROM GLP.SEMANTIC.PRESCRIPTION_CLASS_COMPANY s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_PRESCRIBER
  COMMENT = 'Dataset prescriber of the semantic view DIABETES_MARKET.'
AS SELECT s.PRESCRIBER_ID AS PRESCRIBER_ID, s.CMS_PRESCRIBER_TYPE AS CMS_PRESCRIBER_TYPE, s.CITY AS CITY, s.STATE AS STATE, s.IS_SGLT2_PRESCRIBER AS IS_SGLT2_PRESCRIBER, s.IS_GLP1_PRESCRIBER AS IS_GLP1_PRESCRIBER, s.PRIMARY_SPECIALTY_CODE AS PRIMARY_SPECIALTY_CODE
FROM GLP.SEMANTIC.PRESCRIBER_PROFILE s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_SPECIALTY
  COMMENT = 'Dataset specialty of the semantic view DIABETES_MARKET.'
AS SELECT s.SPECIALTY_CODE AS SPECIALTY_CODE, s.PREF_LABEL_EN AS SPECIALTY_NAME, COALESCE(s.PREF_LABEL_JA, s.PREF_LABEL_EN) AS SPECIALTY_NAME_JA, COALESCE(s.PREF_LABEL_ZH, s.PREF_LABEL_EN) AS SPECIALTY_NAME_ZH
FROM GLP.VOCAB.SPECIALTY s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_PRODUCT
  COMMENT = 'Dataset product of the semantic view DIABETES_MARKET.'
AS SELECT s.PRODUCT_ID AS PRODUCT_ID, s.BRAND_NAME AS BRAND_NAME, s.CMS_GENERIC_NAME AS CMS_GENERIC_NAME, s.IS_COMBINATION AS IS_COMBINATION, s.IS_SGLT2_PRODUCT AS IS_SGLT2_PRODUCT, s.IS_GLP1_PRODUCT AS IS_GLP1_PRODUCT
FROM GLP.SEMANTIC.PRODUCT_PROFILE s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_THERAPEUTIC_CLASS
  COMMENT = 'Dataset therapeutic_class of the semantic view DIABETES_MARKET.'
AS SELECT s.CLASS_ID AS CLASS_ID, s.PREF_LABEL_EN AS CLASS_NAME, s.PREF_LABEL_JA AS CLASS_NAME_JA, s.PREF_LABEL_ZH AS CLASS_NAME_ZH, s.NOTATION AS ATC_CODE, d.DEPTH AS CLASS_DEPTH, d.DEPTH = 3 AS IS_DRUG_CLASS
FROM GLP.VOCAB.THERAPEUTIC_CLASS s LEFT JOIN (SELECT CLASS_ID, COUNT(*) AS DEPTH FROM GLP.VOCAB.CLASS_ANCESTOR GROUP BY CLASS_ID) d ON d.CLASS_ID = s.CLASS_ID;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_ORGANIZATION
  COMMENT = 'Dataset organization of the semantic view DIABETES_MARKET.'
AS SELECT s.ORGANIZATION_ID AS ORGANIZATION_ID, s.NAME_EN AS COMPANY_NAME, COALESCE(s.NAME_JA, s.NAME_EN) AS COMPANY_NAME_JA, COALESCE(s.NAME_ZH, s.NAME_EN) AS COMPANY_NAME_ZH
FROM GLP.US.ORGANIZATION s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_NATIONAL_VALUE
  COMMENT = 'Dataset national_value of the semantic view JAPAN_MARKET.'
AS SELECT s.PRODUCT_ID AS PRODUCT_ID, s.CARE_SETTING_ID AS CARE_SETTING_ID, s.CLASS_ID AS CLASS_ID, s.TOTAL_QUANTITY AS QUANTITY, s.CLASS_TOTAL_VALUE_YEN AS CLASS_TOTAL_VALUE_YEN, s.MARKET_TOTAL_VALUE_YEN AS MARKET_TOTAL_VALUE_YEN, s.VALUE_YEN AS VALUE_YEN
FROM GLP.SEMANTIC.JP_NATIONAL_VALUE_CLASS s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_PREFECTURE_VALUE
  COMMENT = 'Dataset prefecture_value of the semantic view JAPAN_MARKET.'
AS SELECT s.PRODUCT_ID AS PRODUCT_ID, s.CARE_SETTING_ID AS CARE_SETTING_ID, s.CLASS_ID AS CLASS_ID, s.PREFECTURE_CODE AS PREFECTURE_CODE, s.QUANTITY AS QUANTITY, s.VALUE_YEN AS VALUE_YEN
FROM GLP.SEMANTIC.JP_PREFECTURE_VALUE_CLASS s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_MONTH_VALUE
  COMMENT = 'Dataset month_value of the semantic view JAPAN_MARKET.'
AS SELECT s.PRODUCT_ID AS PRODUCT_ID, s.CARE_SETTING_ID AS CARE_SETTING_ID, s.CLASS_ID AS CLASS_ID, s.MONTH AS MONTH, s.QUANTITY AS QUANTITY, s.GENERIC_QUANTITY AS GENERIC_QUANTITY, s.VALUE_YEN AS VALUE_YEN
FROM GLP.SEMANTIC.JP_MONTH_VALUE_CLASS s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_SEX_AGE_VALUE
  COMMENT = 'Dataset sex_age_value of the semantic view JAPAN_MARKET.'
AS SELECT s.PRODUCT_ID AS PRODUCT_ID, s.CARE_SETTING_ID AS CARE_SETTING_ID, s.CLASS_ID AS CLASS_ID, s.SEX_AGE_CODE AS SEX_AGE_CODE, s.QUANTITY AS QUANTITY, s.VALUE_YEN_AGE75PLUS AS VALUE_YEN_AGE75PLUS, s.VALUE_YEN_FEMALE AS VALUE_YEN_FEMALE, s.VALUE_YEN AS VALUE_YEN
FROM GLP.SEMANTIC.JP_SEX_AGE_VALUE_CLASS s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_PRODUCT
  COMMENT = 'Dataset product of the semantic view JAPAN_MARKET.'
AS SELECT s.PRODUCT_ID AS PRODUCT_ID, s.PRODUCT_NAME_JA AS PRODUCT_NAME_JA, s.PRODUCT_NAME AS PRODUCT_NAME, s.YJ_CODE AS YJ_CODE, s.ACTIVE_SUBSTANCES AS ACTIVE_SUBSTANCES, s.ACTIVE_SUBSTANCES_JA AS ACTIVE_SUBSTANCES_JA, s.NHI_PRICE AS NHI_PRICE, s.DISPENSING_UNIT AS DISPENSING_UNIT, s.ROUTE AS ROUTE, s.IS_GENERIC AS IS_GENERIC, s.IS_ORIGINATOR AS IS_ORIGINATOR, s.IS_COMBINATION AS IS_COMBINATION, s.IS_SGLT2_PRODUCT AS IS_SGLT2_PRODUCT, s.IS_GLP1_PRODUCT AS IS_GLP1_PRODUCT, s.MAH_NAME AS MARKETING_AUTHORIZATION_HOLDER, s.MAH_NAME_JA AS MARKETING_AUTHORIZATION_HOLDER_JA, s.COMPANY AS COMPANY, s.COMPANY_JA AS COMPANY_JA, s.JP_CLASS_CODE AS JP_CLASS_CODE
FROM GLP.SEMANTIC.JP_PRODUCT_PROFILE s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_THERAPEUTIC_CLASS
  COMMENT = 'Dataset therapeutic_class of the semantic view JAPAN_MARKET.'
AS SELECT s.CLASS_ID AS CLASS_ID, s.PREF_LABEL_EN AS CLASS_NAME, s.PREF_LABEL_JA AS CLASS_NAME_JA, s.PREF_LABEL_ZH AS CLASS_NAME_ZH, s.NOTATION AS ATC_CODE, d.DEPTH AS CLASS_DEPTH, d.DEPTH = 3 AS IS_DRUG_CLASS
FROM GLP.VOCAB.THERAPEUTIC_CLASS s LEFT JOIN (SELECT CLASS_ID, COUNT(*) AS DEPTH FROM GLP.VOCAB.CLASS_ANCESTOR GROUP BY CLASS_ID) d ON d.CLASS_ID = s.CLASS_ID;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_JP_DRUG_CLASS
  COMMENT = 'Dataset jp_drug_class of the semantic view JAPAN_MARKET.'
AS SELECT s.JP_CLASS_CODE AS JP_CLASS_CODE, s.PREF_LABEL_EN AS JP_CLASS_NAME, s.PREF_LABEL_JA AS JP_CLASS_NAME_JA, s.PREF_LABEL_ZH AS JP_CLASS_NAME_ZH
FROM GLP.VOCAB.JP_DRUG_CLASS s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_PREFECTURE
  COMMENT = 'Dataset prefecture of the semantic view JAPAN_MARKET.'
AS SELECT s.PREFECTURE_CODE AS PREFECTURE_CODE, s.PREF_LABEL_EN AS PREFECTURE_NAME, s.PREF_LABEL_JA AS PREFECTURE_NAME_JA, s.PREF_LABEL_ZH AS PREFECTURE_NAME_ZH
FROM GLP.VOCAB.PREFECTURE s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_CARE_SETTING
  COMMENT = 'Dataset care_setting of the semantic view JAPAN_MARKET.'
AS SELECT s.CARE_SETTING_ID AS CARE_SETTING_ID, s.PREF_LABEL_EN AS CARE_SETTING_NAME, s.PREF_LABEL_JA AS CARE_SETTING_NAME_JA, s.PREF_LABEL_ZH AS CARE_SETTING_NAME_ZH
FROM GLP.VOCAB.CARE_SETTING s;

CREATE OR REPLACE VIEW GLP.SEMANTIC.SV_JP_SEX_AGE_GROUP
  COMMENT = 'Dataset sex_age_group of the semantic view JAPAN_MARKET.'
AS SELECT s.SEX_AGE_CODE AS SEX_AGE_CODE, s.PREF_LABEL_EN AS SEX_AGE_NAME, s.PREF_LABEL_JA AS SEX_AGE_NAME_JA, s.PREF_LABEL_ZH AS SEX_AGE_NAME_ZH, s.SEX AS SEX, s.MIN_AGE AS MIN_AGE
FROM GLP.VOCAB.SEX_AGE_GROUP s;
